#ifndef EzI2C_INCLUDE
#define EzI2C_INCLUDE

#include <m8c.h>

#define EzI2C_SLAVE_ADDR                 0x4
#define EzI2C_DYNAMIC_ADDR               0
#define EzI2C_ROM_ENABLE                 0
#define EzI2C_AUTO_ADDR_CHECK             1                          //CY8C28X45 may have this 0 or 1 while all other have 0
#define EzI2C_ADDR_REG_PRESENT            1                          //CY8C28X45 have 1 always while all other have 0
#define EzI2C_CY8C22x45                   0                          // 1 if it is CY8C22x45 device, otherwice 0

/* Create pragmas to support proper argument and return value passing */
#pragma fastcall16  EzI2C_Start
#pragma fastcall16  EzI2C_DisableInt
#pragma fastcall16  EzI2C_EnableInt
#pragma fastcall16  EzI2C_ResumeInt
#pragma fastcall16  EzI2C_Stop
#pragma fastcall16  EzI2C_DisableSlave
#pragma fastcall16  EzI2C_SetRamBuffer
#pragma fastcall16  EzI2C_GetAddr
#pragma fastcall16  EzI2C_GetActivity

#if (EzI2C_DYNAMIC_ADDR | EzI2C_AUTO_ADDR_CHECK)
#pragma fastcall16  EzI2C_SetAddr
#endif

#if ( EzI2C_ROM_ENABLE )
#pragma fastcall16  EzI2C_SetRomBuffer
#endif

#if (EzI2C_CY8C22x45)
#pragma fastcall16  EzI2C_EnableHWAddrCheck
#pragma fastcall16  EzI2C_DisableHWAddrCheck
#endif

//-------------------------------------------------
// Constants for EzI2C_bBusy_Flag
//-------------------------------------------------
//
//
#define EzI2C_I2C_FREE                 0x00    // No transaction at the current moment
#define EzI2C_I2C_BUSY_RAM_READ        0x01    // RAM read transaction in progress
#define EzI2C_I2C_BUSY_RAM_WRITE       0x02    // RAM write transaction in progress
#define EzI2C_I2C_BUSY_ROM_READ        0x04    // ROM read transaction in progress
#define EzI2C_I2C_BUSY_ROM_WRITE       0x08    // ROM write transaction in progress

//-------------------------------------------------
// Constants for EzI2C API's.
//-------------------------------------------------
//
//
#define EzI2C_ACTIVITY_MASK   0xB0
#define EzI2C_ANY_ACTIVITY    0x80
#define EzI2C_READ_ACTIVITY   0x20
#define EzI2C_WRITE_ACTIVITY  0x10

//-------------------------------------------------
// Prototypes of the EzI2C API.
//-------------------------------------------------
extern void  EzI2C_Start(void);                                         // Proxy Class 1, if Static Address
                                                                                   // Proxy Class 4, if Dynamic Address
extern void  EzI2C_DisableInt(void);                                    // Proxy Class 1
extern void  EzI2C_EnableInt(void);                                     // Proxy Class 1
extern void  EzI2C_ResumeInt(void);                                     // Proxy Class 1
extern void  EzI2C_Stop(void);                                          // Proxy Class 1
extern void  EzI2C_DisableSlave(void);                                  // Proxy Class 1
extern void  EzI2C_SetRamBuffer(BYTE bSize, BYTE bRWBoundary, BYTE * pAddr); // Proxy Class 4 
extern BYTE  EzI2C_GetAddr(void);                                       // Proxy Class 4
extern BYTE  EzI2C_GetActivity(void);                                   // Proxy Class 4

#if (EzI2C_DYNAMIC_ADDR | EzI2C_AUTO_ADDR_CHECK)
extern void  EzI2C_SetAddr(BYTE bAddr);                                 // Proxy Class 4
#endif

#if ( EzI2C_ROM_ENABLE )
extern void  EzI2C_SetRomBuffer(BYTE bSize, const BYTE * pAddr);        // Proxy Class 4
#endif

#if ( EzI2C_CY8C22x45 ) 
extern void  EzI2C_EnableHWAddrCheck(void);
extern void  EzI2C_DisableHWAddrCheck(void);
#endif

//-------------------------------------------------
// Define global variables.                 
//-------------------------------------------------
#if ( EzI2C_DYNAMIC_ADDR )
#if ( EzI2C_AUTO_ADDR_CHECK^1 )
extern   BYTE   EzI2C_bAddr;                                            // Proxy Class 1
#endif
#endif

extern   BYTE   EzI2C_bBusy_Flag;

#endif
